arguments.command:
cd /workspace && cat > sitecustomize.py <<'PY'
import os
import subprocess
_original_popen = subprocess.Popen
def _bounded_popen(*args, **kwargs):
    kwargs['start_new_session'] = False
    return _original_popen(*args, **kwargs)
subprocess.Popen = _bounded_popen
_original_killpg = os.killpg
def _bounded_killpg(pid, sig):
    try:
        return _original_killpg(pid, sig)
    except (PermissionError, ProcessLookupError):
        try:
            os.kill(pid, sig)
        except (PermissionError, ProcessLookupError):
            pass
os.killpg = _bounded_killpg
PY
export PYTHONPATH=/workspace
python3 check.py submission
status=$?
rm -f sitecustomize.py
exit $status
